{
  "probability": 0.96,
  "range_low": 0.92,
  "range_high": 0.99,
  "summary": [
    "606 Mediterranean deaths were reported by February 2026, implying a high March toll if the pace continues.",
    "Data gaps and potential undercounts may mean the true toll is higher than reported, supporting a higher end-of-March outcome.",
    "Adverse weather and sea-state conditions, along with SAR capacity constraints and policy shifts, create upward pressure on fatalities in March.",
    "Seasonal risk in early spring further reinforces the likelihood of reaching or exceeding 900 deaths by end-March 2026."
  ],
  "confidence": "high",
  "narrative": "Starting from the Feb 2026 pace (about 606 deaths), March would need around 300+ more deaths to reach 900 by end-March. Given persistent high crossing pressure, data gaps, weather risks, and policy/SAR factors, a 96% posterior probability of hitting the 900-toll threshold is justified, with some uncertainty from reporting lags.",
  "justification": {
    "anchor": {
      "probability": 0.60,
      "basis": "reference class anchored to the short-term Mediterranean death pace observed through February 2026 (606 deaths by Feb 24) and the assumption that March could continue at a similar high rate, providing a conservative starting probability prior to factor updates."
    },
    "factor_updates": [
      {
        "factor": "Pace of Mediterranean deaths through February 2026 implies high March toll",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "606 deaths by Feb 24 suggests a credible path to 900 by end-March if March follows the same tempo."
      },
      {
        "factor": "March weather and sea-state conditions increasing fatality risk",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Stormier seas and poor conditions historically raise fatalities, pushing March toll higher."
      },
      {
        "factor": "Data reporting gaps / undercount risk in Missing Migrants Project",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "UN briefings note gaps and verification challenges; true toll could be higher than reported, elevating end-March total."
      },
      {
        "factor": "Policy shifts and SAR capacity constraints reducing safe pathways",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Stricter controls and limited rescues can increase deaths for given crossing pressure, lifting the tally."
      },
      {
        "factor": "Potential for large single incidents to push March toll upward",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "A single mass casualty event could spike monthly totals, though unlikely to alone drive to 900 without other supporting factors."
      }
    ],
    "synthesis_rationale": "The factors were integrated as Bayesian-like updates, with each upward signal increasing the posterior probability toward hitting 900 by end-March. Correlations among pace, data gaps, and weather/policy conditions were acknowledged; the combined exposure to persistent high crossing pressure and possible undercount justifies a high calibrated probability with a tight upper bound, while recognizing reporting lags introduce residual uncertainty."
  }
}

{
  "probability": 0.96,
  "range_low": 0.92,
  "range_high": 0.98,
  "summary": [
    "February 2026 pace shows 606 Mediterranean deaths by Feb 24, suggesting March-end toll could plausibly reach 900 if the pace persists.",
    "Multiple upward drivers (pace continuation, data gaps, weather, SAR capacity, seasonal risk) push the near-term toll higher, supporting a high posterior probability.",
    "A downward countervailing factor (policy crackdowns reducing crossings) tempers the rise, but is not enough to offset the momentum from the other drivers.",
    "Bayesian synthesis yields a 96% posterior probability with a 0.92–0.98 range, acknowledging data gaps and correlated factors."
  ],
  "confidence": "high",
  "narrative": "Starting from the February 2026 pace (606 deaths by Feb 24), several independent drivers push the March toll upward, including continued high crossing pressure and adverse weather, while data gaps may conceal additional deaths. While policy restrictions could dampen crossings, the balance of evidence favors reaching or exceeding 900 deaths before April, yielding a posterior probability near 0.96 with a narrow calibrated range.",
  "justification": {
    "anchor": {
      "probability": 0.71,
      "basis": "Using February 2026 pace of 606 deaths by Feb 24 as the near-term reference class; anchor probability 0.71 chosen as a reasonable central estimate for reaching 900 by end-March given current trajectory."
    },
    "factor_updates": [
      {
        "factor": "March 2026 pace continuation",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "606 deaths by Feb 24 implies that March could add a sizable number; if March mirrors February, reaching 900 by end-March is plausible."
      },
      {
        "factor": "Missing Migrants Project data gaps / undercount",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "UN Geneva briefings flag data gaps; unreported or late-reported deaths could push the March tally higher than currently observed."
      },
      {
        "factor": "Weather and sea-state conditions across the Central Mediterranean",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Stormier seas and poor conditions raise fatality risk on crossings, increasing the March toll."
      },
      {
        "factor": "SAR capacity and policy environment affecting rescues",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Policy constraints or limited rescue capacity can raise casualties; continued high-risk crossings without proportional rescue could push totals higher."
      },
      {
        "factor": "Seasonal risk pattern in early spring",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Seasonal factors historically elevate crossing attempts and risks as winter gives way to spring."
      },
      {
        "factor": "European/regional policy crackdown reducing irregular crossings",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Stricter border controls and reduced rescue capacity may lower crossing attempts and deaths in the near term."
      },
      {
        "factor": "Potential for large single incidents to push March toll upward",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Mass casualty events can spike monthly tallies, but a single incident is unlikely to drive the March total to 900 on its own."
      }
    ],
    "synthesis_rationale": "The anchor (0.71) is adjusted upward by multiple moderately-sized, directionally reinforcing factors (pace continuation, data gaps, weather, SAR/changing conditions, and seasonal risk), with a modest downward adjustment from policy-restriction effects. The factors are plausibly correlated (e.g., high crossing pressure increasing both death risk and reporting), so the net uplift yields a high posterior of 0.96, within a tight calibration band (0.92–0.98) to reflect uncertainty and data-lag risks."
  }
}

